import json
from copy import deepcopy

def zebra_solver():
    houses = {1, 2, 3, 4}

    categories = {
        "Name": ["Peter", "Alice", "Eric", "Arnold"],
        "Hobby": ["cooking", "painting", "gardening", "photography"],
        "Animal": ["horse", "fish", "cat", "bird"],
        "BookGenre": ["fantasy", "mystery", "romance", "science fiction"],
        "Birthday": ["april", "jan", "sept", "feb"],
        "MusicGenre": ["pop", "rock", "classical", "jazz"],
    }

    # Variables are tuples (category, item), domain is set of house numbers
    vars_list = []
    for cat, items in categories.items():
        for item in items:
            vars_list.append((cat, item))

    domains = {var: set(houses) for var in vars_list}

    # Constraints
    equal_pairs = []
    direct_left_pairs = []  # A is directly left of B: pos(A) + 1 == pos(B)
    right_of_pairs = []     # A is somewhere right of B: pos(A) > pos(B)
    unary_not_in = []       # (var, house) meaning var != house

    # Clues modeled as constraints:

    # 1. cooking == romance
    equal_pairs.append((("Hobby", "cooking"), ("BookGenre", "romance")))
    # 2. feb == pop
    equal_pairs.append((("Birthday", "feb"), ("MusicGenre", "pop")))
    # 3. Eric != house 2
    unary_not_in.append((("Name", "Eric"), 2))
    # 4. romance != house 4
    unary_not_in.append((("BookGenre", "romance"), 4))
    # 5. feb == fish
    equal_pairs.append((("Birthday", "feb"), ("Animal", "fish")))
    # 6. Alice right of fantasy
    right_of_pairs.append((("Name", "Alice"), ("BookGenre", "fantasy")))
    # 7. horse == rock
    equal_pairs.append((("Animal", "horse"), ("MusicGenre", "rock")))
    # 8. gardening == april
    equal_pairs.append((("Hobby", "gardening"), ("Birthday", "april")))
    # 9. jazz == cooking
    equal_pairs.append((("MusicGenre", "jazz"), ("Hobby", "cooking")))
    # 10. rock == mystery
    equal_pairs.append((("MusicGenre", "rock"), ("BookGenre", "mystery")))
    # 11. painting directly left of romance
    direct_left_pairs.append((("Hobby", "painting"), ("BookGenre", "romance")))
    # 12. Peter == pop
    equal_pairs.append((("Name", "Peter"), ("MusicGenre", "pop")))
    # 13. gardening == Arnold
    equal_pairs.append((("Hobby", "gardening"), ("Name", "Arnold")))
    # 14. rock directly left of jan
    direct_left_pairs.append((("MusicGenre", "rock"), ("Birthday", "jan")))
    # 15. cooking != house 3
    unary_not_in.append((("Hobby", "cooking"), 3))
    # 16. cat right of horse
    right_of_pairs.append((("Animal", "cat"), ("Animal", "horse")))

    # Apply unary constraints
    for (var, h) in unary_not_in:
        if h in domains[var]:
            domains[var].remove(h)

    # Propagation functions
    def propagate(dom):
        changed = True
        while changed:
            changed = False

            # Enforce equality constraints
            for a, b in equal_pairs:
                inter = dom[a] & dom[b]
                if inter != dom[a]:
                    dom[a] = set(inter)
                    changed = True
                if inter != dom[b]:
                    dom[b] = set(inter)
                    changed = True
                if not dom[a] or not dom[b]:
                    return False

            # Enforce direct left constraints
            for a, b in direct_left_pairs:
                da = dom[a]
                db = dom[b]
                allowed_a = set(x for x in da if x + 1 in db)
                allowed_b = set(x for x in db if x - 1 in da)
                if allowed_a != da:
                    dom[a] = allowed_a
                    changed = True
                if allowed_b != db:
                    dom[b] = allowed_b
                    changed = True
                if not dom[a] or not dom[b]:
                    return False

            # Enforce right-of constraints
            for a, b in right_of_pairs:
                da = dom[a]
                db = dom[b]
                allowed_a = set(x for x in da if any(y < x for y in db))
                allowed_b = set(y for y in db if any(x > y for x in da))
                if allowed_a != da:
                    dom[a] = allowed_a
                    changed = True
                if allowed_b != db:
                    dom[b] = allowed_b
                    changed = True
                if not dom[a] or not dom[b]:
                    return False

            # All-different within each category
            for cat, items in categories.items():
                # collect assigned houses in this category
                assigned_houses = set()
                for item in items:
                    var = (cat, item)
                    if len(dom[var]) == 1:
                        assigned_houses |= dom[var]
                # remove assigned from others
                for item in items:
                    var = (cat, item)
                    if len(dom[var]) > 1:
                        new_set = dom[var] - assigned_houses
                        if new_set != dom[var]:
                            dom[var] = new_set
                            changed = True
                        if not dom[var]:
                            return False

        return True

    def is_complete(dom):
        return all(len(v) == 1 for v in dom.values())

    def select_unassigned_variable(dom):
        # Minimum Remaining Values heuristic
        candidates = [var for var in dom if len(dom[var]) > 1]
        if not candidates:
            return None
        return min(candidates, key=lambda v: len(dom[v]))

    def backtrack(dom):
        if not propagate(dom):
            return None
        if is_complete(dom):
            return dom
        var = select_unassigned_variable(dom)
        if var is None:
            return None
        for value in sorted(dom[var]):
            new_dom = {k: set(v) for k, v in dom.items()}
            new_dom[var] = {value}
            result = backtrack(new_dom)
            if result is not None:
                return result
        return None

    solution_domains = backtrack(domains)
    if solution_domains is None:
        raise ValueError("No solution found")

    # Build output
    # Invert mapping to get per-house attribute values
    inverted = {cat: {} for cat in categories}
    for cat, items in categories.items():
        for item in items:
            house = next(iter(solution_domains[(cat, item)]))
            inverted[cat][house] = item

    header = ["House", "Name", "Hobby", "Animal", "BookGenre", "Birthday", "MusicGenre"]
    rows = []
    for h in [1, 2, 3, 4]:
        row = [
            str(h),
            inverted["Name"][h],
            inverted["Hobby"][h],
            inverted["Animal"][h],
            inverted["BookGenre"][h],
            inverted["Birthday"][h],
            inverted["MusicGenre"][h],
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = zebra_solver()
    print(json.dumps(result, ensure_ascii=False, indent=2))
